# Crop classifications transcribed from GB 2763-2026 Annex A, PDF pp.413–415.
CATALOG=[]
def add(category,group,entries,part,page,subgroups=()):
 for entry in entries.split('|'):
  terms=entry.split(':');zh,en=terms[:2];aliases=terms[2].split(',') if len(terms)>2 else []
  CATALOG.append(dict(id=zh,zh=zh,en=en,aliases=aliases,category=category,groups=[category,group,*subgroups],part=part,annexPage=page))
